# Illustrative pattern: keep updates out of the principal directions
U, S, Vt = svd(W)                  # singular directions of one weight matrix
P = U[:, :k]                       # top-k principal directions: protected

def fenced(grad):
    # remove the part of the update that lies along protected directions
    return grad - P @ (P.T @ grad)

for batch in task_batches:
    grad = loss(W, batch).grad()
    W = W - lr * fenced(grad)      # learning happens in the bottom subspace
    if time_to_refresh():
        U, S, Vt = svd(W)          # directions move as W moves
        P = U[:, :k]
